practice.solution:
from itertools import product

def statement(k, p, q, r):
    if k == 1:
        return p or not p
    elif k == 2:
        return p and not p
    elif k == 3:
        return p or q
    elif k == 4:
        return p or not (p and q)
    elif k == 5:
        return (p or q) and not (p or q)
    elif k == 6:
        return (p or q or r) or (not p and not q and not r)
    elif k == 7:
        return (p or q) and not (p and q)
    return p and (q or r)

count = int(input())
for j in range(count):
    k = int(input())
    true_rows = 0
    for p, q, r in product([True, False], repeat=3):
        true_rows = true_rows + statement(k, p, q, r)
    kind = "a contingency"
    if true_rows == 8:
        kind = "a tautology"
    elif true_rows == 0:
        kind = "a contradiction"
    print(f"statement {k}: true in {true_rows} of 8 rows, {kind}")
